import React from 'react';
import {AboutContainer,ImageWrapper,TextWrapper} from './styles';
import fotoAbout from '../../../assets/images/about-image.png';
import {FiCheck} from 'react-icons/fi';


const  About = () => {
    return(
        <AboutContainer>
            <TextWrapper>
                <h2>Real Estate Investment Platform</h2>
                <ul>
                    <li><FiCheck /> Find Real Estate Deals</li>
                    <li> Send & Receive Offers Online</li>
                    <li> Your Own Real Estate Website</li>
                    <li> Post Real Estate Deals</li>
                    <li> Chat Owners & Cash Buyers</li>
                    <li> Create Landing Pages</li>
                </ul>
            </TextWrapper>
            <ImageWrapper>
                <img src={fotoAbout} alt='photo-about'/>
            </ImageWrapper>
            
        </AboutContainer>
      
    )
}

export default About;
